pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 depositAmount, address collector, uint256 collectAmount) public {
        // Bound values to keep within admissible domain
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);

        // Avoid address collisions with the contract itself
        vm.assume(collector != address(0));
        vm.assume(collector != address(c));

        // Initialize the contract by setting MinSum and initializing
        vm.prank(collector);
        c.SetMinSum(0);
        vm.prank(collector);
        c.Initialized();

        // Give collector some Ether to perform the collect
        vm.deal(collector, collectAmount);

        // Deposit from msg.sender=collector to populate balances
        vm.prank(collector);
        c.Deposit{value: depositAmount}();

        // Record balances after deposit
        uint256 balanceAfterDeposit = c.balances(collector);

        // Set log file to a valid address to avoid revert during deposit/collect
        c.SetLogFile(address(0x1));

        // Collect with Ether
        vm.prank(collector);
        c.Collect{value: collectAmount}(collectAmount);

        // After deposit and collect, the balance of collector should be depositAmount - collectAmount
        uint256 expectedBalance = depositAmount - collectAmount;
        uint256 actualBalance = c.balances(collector);

        // Invariant check: The balance of the collector must equal the net deposit (deposit - collect)
        // This holds in the reference version, but fails in the buggy version because deposits are
        // credited to address(0) instead of msg.sender, breaking the accounting.
        // The assertion verifies that the collector's balance reflects the operations on their address.
        assertEq(actualBalance, expectedBalance, "Collector balance must equal net deposit");
    }
}

