pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address user, address other) public {
        vm.assume(user != address(0));
        vm.assume(other != address(0));
        vm.assume(user != other);
        vm.assume(depositAmount > 0 && depositAmount < 1e36);

        // Initialize the contract
        c.SetMinSum(0);
        c.Initialized();

        // Deposit from the user
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        // Deposit from another address to have non-zero total balance
        uint256 otherDeposit = 1 ether;
        vm.deal(other, otherDeposit);
        vm.prank(other);
        c.Deposit{value: otherDeposit}();

        // Try to collect from the user
        uint256 userBalanceBefore = c.balances(user);
        collectAmount = bound(collectAmount, 1, userBalanceBefore);
        vm.prank(user);
        c.Collect(collectAmount);

        // Calculate the expected total ether balance: sum of all balances
        uint256 totalRecorded = c.balances(user) + c.balances(other);
        uint256 contractBalance = address(c).balance;
        assertTrue(totalRecorded == contractBalance);
    }
}

