pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 collectAmt, address user1, address user2) public {
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2 && user1 != address(c) && user2 != address(c));
        amount1 = bound(amount1, 1, type(uint256).max / 2);
        amount2 = bound(amount2, 1, type(uint256).max / 2);
        collectAmt = bound(collectAmt, 0, type(uint256).max);

        c.Initialized();
        c.SetMinSum(0);

        LogFile lf = new LogFile();
        c.SetLogFile(address(lf));

        vm.deal(user1, amount1 + amount2);
        vm.prank(user1);
        c.Deposit{value: amount1}();

        vm.deal(user2, amount2);
        vm.prank(user2);
        c.Deposit{value: amount2}();

        uint256 balUser1 = c.balances(user1);
        collectAmt = bound(collectAmt, 0, balUser1);

        if (collectAmt > 0 && balUser1 >= collectAmt) {
            vm.prank(user1);
            c.Collect(collectAmt);
        }

        uint256 balUser2 = c.balances(user2);
        assertEq(
            c.balances(user1) + c.balances(user2),
            address(c).balance,
            "Sum of balances should equal contract ETH balance"
        );
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

